"use client";

import { useReducer, useEffect, useCallback } from "react";
import { GameState, GameAction } from "@/lib/tetris/types";
import {
  initGame,
  tick,
  moveLeft,
  moveRight,
  softDrop,
  hardDrop,
  rotate,
  togglePause,
} from "@/lib/tetris/gameEngine";
import { getDropInterval } from "@/lib/tetris/scoring";
import GameBoard from "./GameBoard";
import NextPiece from "./NextPiece";
import ScorePanel from "./ScorePanel";
import ControlsInfo from "./ControlsInfo";
import GameOverOverlay from "./GameOverOverlay";

function gameReducer(state: GameState, action: GameAction): GameState {
  switch (action.type) {
    case "TICK":
      return tick(state);
    case "MOVE_LEFT":
      return moveLeft(state);
    case "MOVE_RIGHT":
      return moveRight(state);
    case "SOFT_DROP":
      return softDrop(state);
    case "HARD_DROP":
      return hardDrop(state);
    case "ROTATE_CW":
      return rotate(state, 1);
    case "ROTATE_CCW":
      return rotate(state, -1);
    case "TOGGLE_PAUSE":
      return togglePause(state);
    case "RESTART":
      return initGame();
  }
}

export default function TetrisGame() {
  const [state, dispatch] = useReducer(gameReducer, null, initGame);

  // Gravity tick
  useEffect(() => {
    if (state.isGameOver || state.isPaused) return;

    const interval = getDropInterval(state.level);
    const timer = setInterval(() => dispatch({ type: "TICK" }), interval);
    return () => clearInterval(timer);
  }, [state.level, state.isGameOver, state.isPaused]);

  // Keyboard controls
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      // Allow restart anytime during game over
      if (state.isGameOver) {
        if (e.key === "r" || e.key === "R") {
          e.preventDefault();
          dispatch({ type: "RESTART" });
        }
        return;
      }

      switch (e.key) {
        case "ArrowLeft":
        case "a":
        case "A":
          e.preventDefault();
          dispatch({ type: "MOVE_LEFT" });
          break;
        case "ArrowRight":
        case "d":
        case "D":
          e.preventDefault();
          dispatch({ type: "MOVE_RIGHT" });
          break;
        case "ArrowDown":
        case "s":
        case "S":
          e.preventDefault();
          dispatch({ type: "SOFT_DROP" });
          break;
        case "ArrowUp":
        case "w":
        case "W":
          e.preventDefault();
          dispatch({ type: "ROTATE_CW" });
          break;
        case "z":
        case "Z":
          e.preventDefault();
          dispatch({ type: "ROTATE_CCW" });
          break;
        case " ":
          e.preventDefault();
          dispatch({ type: "HARD_DROP" });
          break;
        case "p":
        case "P":
          e.preventDefault();
          dispatch({ type: "TOGGLE_PAUSE" });
          break;
        case "r":
        case "R":
          e.preventDefault();
          dispatch({ type: "RESTART" });
          break;
      }
    },
    [state.isGameOver]
  );

  useEffect(() => {
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className="flex gap-6 items-start">
      <div className="relative">
        <GameBoard gameState={state} />
        {state.isPaused && !state.isGameOver && (
          <div className="absolute inset-0 bg-black/60 flex items-center justify-center rounded">
            <span className="text-white text-3xl font-bold">PAUSED</span>
          </div>
        )}
        {state.isGameOver && (
          <GameOverOverlay
            score={state.score}
            onRestart={() => dispatch({ type: "RESTART" })}
          />
        )}
      </div>
      <div className="flex flex-col gap-4">
        <div className="bg-gray-800 border border-gray-600 rounded p-3">
          <div className="text-gray-400 text-xs uppercase tracking-wider mb-2">Next</div>
          <NextPiece pieceType={state.nextPiece} />
        </div>
        <ScorePanel
          score={state.score}
          level={state.level}
          linesCleared={state.linesCleared}
        />
        <ControlsInfo />
      </div>
    </div>
  );
}

